<section class="single-herbs-guide__section" aria-labelledby="topic-twelve-questions"><h4 id="topic-twelve-questions"><?php echo s($damptext('Yang questions for this category', 'Preguntas de Yang para esta categoría')); ?></h4><p class="single-herbs-guide__section-lead"><?php echo s($damptext('One reversible deck keeps the chapter 5 distinctions together.', 'Una sola baraja reversible mantiene juntas las distinciones del capítulo 5.')); ?></p><div class="single-herbs-guide__yang-deck" data-yang-deck data-card-label="<?php echo s($damptext('Card', 'Tarjeta')); ?>" data-of-label="<?php echo s($damptext('of', 'de')); ?>"><?php foreach ($dampquestions as $i => $q): ?><article class="single-herbs-guide__yang-card<?php echo $i === 0 ? ' is-active' : ''; ?>" data-yang-card aria-hidden="<?php echo $i === 0 ? 'false' : 'true'; ?>"><div class="single-herbs-guide__yang-face single-herbs-guide__yang-face--front"><span class="single-herbs-guide__yang-label"><?php echo s($damptext('Question', 'Pregunta')); ?> <?php echo $i + 1; ?> <?php echo s($damptext('of', 'de')); ?> <?php echo count($dampquestions); ?> · Yang, <?php echo s($damptext('Chapter', 'capítulo')); ?> 5</span><p class="single-herbs-guide__yang-question"><?php echo s($q[0]); ?></p></div><div class="single-herbs-guide__yang-face single-herbs-guide__yang-face--back"><span class="single-herbs-guide__yang-label"><?php echo s($damptext('Answer', 'Respuesta')); ?> <?php echo $i + 1; ?></span><p class="single-herbs-guide__yang-answer"><?php echo s($q[1]); ?></p></div></article><?php endforeach; ?><div class="single-herbs-guide__yang-controls"><button class="single-herbs-guide__yang-control" type="button" data-yang-prev>← <?php echo s($damptext('Previous', 'Anterior')); ?></button><button class="single-herbs-guide__yang-control single-herbs-guide__yang-control--flip" type="button" data-yang-flip data-show-label="<?php echo s($damptext('Show answer', 'Mostrar respuesta')); ?>" data-hide-label="<?php echo s($damptext('Show question', 'Mostrar pregunta')); ?>"><?php echo s($damptext('Show answer', 'Mostrar respuesta')); ?></button><button class="single-herbs-guide__yang-control single-herbs-guide__yang-control--next" type="button" data-yang-next><?php echo s($damptext('Next', 'Siguiente')); ?> →</button></div><p class="single-herbs-guide__yang-progress" data-yang-progress><?php echo s($damptext('Card', 'Tarjeta')); ?> 1 <?php echo s($damptext('of', 'de')); ?> <?php echo count($dampquestions); ?></p></div></section>

